entries[56943] = { ["name"] = "Glyph of Frenzied Regeneration", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ethereal Ink (3)\nMajor Glyph\nClasses: Druid\n25\nUse: Permanently teaches you this glyph.\n\nFor 6 sec after activating Frenzied Regeneration, healing effects on you are 40% more powerful. However, your Frenzied Regeneration now always costs 50 Rage and no longer converts Rage into health." }
entries[56944] = { ["name"] = "Glyph of Omens", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Druid\n25\nUse: Permanently teaches you this glyph.\n\nWhile you are not in an Eclipse, the following abilities now grant 10 Solar or Lunar Energy: Entangling Roots, Cyclone, Faerie Fire, Faerie Swarm, Mass Entanglement, Typhoon, Disorienting Roar, Ursol's Vortex, and Mighty Bash." }
