entries[56946] = { ["name"] = "Glyph of Hurricane", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Druid\n25\nUse: Permanently teaches you this glyph.\n\nYour Hurricane and Astral Storm abilities now also slow the movement speed of their victims by 50%." }
entries[56947] = { ["name"] = "Glyph of Innervate", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Druid\n25\nUse: Permanently teaches you this glyph.\n\nWhen Innervate is cast on a target other than the caster, both the caster and target will benefit, but at 40% reduced effect." }
entries[56948] = { ["name"] = "Glyph of the Orca", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Jadefire Ink (3)\nMinor Glyph\nClasses: Druid\n25\nUse: Permanently teaches you this glyph.\n\nYour Aquatic Form now appears as an Orca." }
entries[56949] = { ["name"] = "Glyph of Efflorescence", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Druid\n25\nUse: Permanently teaches you this glyph.\n\nThe Efflorescence effect is now caused by your Wild Mushroom instead of by Swiftmend, and lasts as long as the Wild Mushroom is active. Additionally, increases the healing done by Swiftmend by 20%." }
entries[56950] = { ["name"] = "Glyph of the Stag", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMinor Glyph\nClasses: Druid\n25\nUse: Permanently teaches you this glyph.\n\nYour Travel Form can now be used as a mount by party members. This glyph is disabled while Glyph of the Cheetah is active." }
entries[56951] = { ["name"] = "Glyph of Savagery", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Lion's Ink (3)\nMajor Glyph\nClasses: Druid\n25\nUse: Permanently teaches you this glyph.\n\nSavage Roar can now be used with 0 combo points, resulting in a 12 sec duration." }
entries[56952] = { ["name"] = "Glyph of Pounce", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ethereal Ink (3)\nMajor Glyph\nClasses: Druid\n25\nUse: Permanently teaches you this glyph.\n\nIncreases the range of your Pounce by 8 yards." }
entries[56953] = { ["name"] = "Glyph of Rebirth", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Jadefire Ink (3)\nMajor Glyph\nClasses: Druid\n25\nUse: Permanently teaches you this glyph.\n\nPlayers resurrected by Rebirth are returned to life with 100% health." }
entries[56954] = { ["name"] = "Glyph of Regrowth", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Druid\n25\nUse: Permanently teaches you this glyph.\n\nIncreases the critical strike chance of your Regrowth by 40%, but removes the periodic component of the spell." }
entries[56955] = { ["name"] = "Glyph of Rejuvenation", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Midnight Ink (3)\nMajor Glyph\nClasses: Druid\n25\nUse: Permanently teaches you this glyph.\n\nWhen you have Rejuvenation active on three or more targets, the cast time of your Nourish spell is reduced by 30%." }
entries[56956] = { ["name"] = "Glyph of Prowl", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Celestial Ink (3)\nMajor Glyph\nClasses: Druid\n25\nUse: Permanently teaches you this glyph.\n\nReduces the movement penalty of Prowl by 100%." }
entries[56957] = { ["name"] = "Glyph of Shred", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Shimmering Ink (3)\nMajor Glyph\nClasses: Druid\n25\nUse: Permanently teaches you this glyph.\n\nWhile Berserk or Tiger's Fury is active, Shred has no positional requirement." }
entries[56958] = { ["name"] = "Glyph of Skull Bash", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Druid\n25\nUse: Permanently teaches you this glyph.\n\nIncreases the duration of your Skull Bash interrupt by 2 sec, but increases the cooldown by 5 sec." }
entries[56959] = { ["name"] = "Glyph of Guided Stars", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Celestial Ink (3)\nMajor Glyph\nClasses: Druid\n25\nUse: Permanently teaches you this glyph.\n\nYour Starfall only hits targets affected by your Moonfire or Sunfire." }
entries[56960] = { ["name"] = "Glyph of Stampede", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Druid\n25\nUse: Permanently teaches you this glyph.\n\nYou can now cast Stampeding Roar without being in Bear Form or Cat Form." }
entries[56961] = { ["name"] = "Glyph of Maul", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Midnight Ink (3)\nMajor Glyph\nClasses: Druid\n25\nUse: Permanently teaches you this glyph.\n\nYour Maul ability now hits 1 additional target for 50% damage." }
entries[56963] = { ["name"] = "Glyph of Nature's Grasp", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Midnight Ink (3)\nMajor Glyph\nClasses: Druid\n25\nUse: Permanently teaches you this glyph.\n\nReduces the cooldown of Nature's Grasp by 45 sec." }
entries[56965] = { ["name"] = "Glyph of Stars", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMinor Glyph\nClasses: Druid\n25\nUse: Permanently teaches you this glyph.\n\nYour Moonkin Form now appears as Astral Form, conferring all the same benefits, but appearing as an astrally enhanced version of your normal humanoid form." }
entries[56966] = { ["name"] = "Boundary Warning", ["text"] = "Unlimited range\nInstant\nThis vehicle is out of bounds. Return to the field of battle at once!" }
entries[56969] = { ["name"] = "Arcane Blast", ["text"] = "30 yd range\n2.5 sec cast\nBlasts the target with energy, dealing 4375 to 5625 Arcane damage. Each time you cast Arcane Blast, spell casting time is reduced. Effect stacks up to 5 times and lasts 8 sec." }
entries[56971] = { ["name"] = "Glyph of Loose Mana", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Lion's Ink (3)\nMinor Glyph\nClasses: Mage\n25\nUse: Permanently teaches you this glyph.\n\nYour Mana Gem now restores mana over 6 sec, rather than instantly." }
entries[56972] = { ["name"] = "Glyph of Arcane Explosion", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ethereal Ink (3)\nMajor Glyph\nClasses: Mage\n25\nUse: Permanently teaches you this glyph.\n\nIncreases the radius of your Arcane Explosion by 5 yards." }
entries[56973] = { ["name"] = "Glyph of Blink", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Lion's Ink (3)\nMajor Glyph\nClasses: Mage\n25\nUse: Permanently teaches you this glyph.\n\nIncreases the distance you travel with the Blink spell by 8 yards." }
entries[56974] = { ["name"] = "Glyph of Evocation", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Jadefire Ink (3)\nMajor Glyph\nClasses: Mage\n25\nUse: Permanently teaches you this glyph.\n\nYour Evocation ability also causes you to regain 60% of your health over its duration.\n\nWith the Invocation talent, you instead gain 10% of your health upon completing an Evocation.\n\nWith the Rune of Power talent, you gain 1% of your health per second while standing in your own Rune of Power." }
entries[56975] = { ["name"] = "Glyph of Combustion", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Mage\n25\nUse: Permanently teaches you this glyph.\n\nIncreases the direct damage, the duration of the damage over time effect and the cooldown of Combustion by 100%." }
entries[56976] = { ["name"] = "Glyph of Frost Nova", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Midnight Ink (3)\nMajor Glyph\nClasses: Mage\n25\nUse: Permanently teaches you this glyph.\n\nReduces the cooldown of Frost Nova by 5 sec." }
entries[56978] = { ["name"] = "Glyph of Momentum", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Midnight Ink (3)\nMinor Glyph\nClasses: Mage\n25\nUse: Permanently teaches you this glyph.\n\nYour Blink spell teleports you in the direction you are moving instead of the direction you are facing." }
entries[56979] = { ["name"] = "Glyph of Ice Block", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Celestial Ink (3)\nMajor Glyph\nClasses: Mage\n25\nUse: Permanently teaches you this glyph.\n\nWhen Ice Block terminates, it triggers an instant free Frost Nova and makes you immune to all spells for 3 sec." }
entries[56980] = { ["name"] = "Glyph of Splitting Ice", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Mage\n25\nUse: Permanently teaches you this glyph.\n\nYour Ice Lance and Icicles now hit 1 additional target for 50% damage." }
entries[56981] = { ["name"] = "Glyph of Cone of Cold", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Jadefire Ink (3)\nMajor Glyph\nClasses: Mage\n25\nUse: Permanently teaches you this glyph.\n\nIncreases the damage done by Cone of Cold by 200%." }
entries[56983] = { ["name"] = "Glyph of Rapid Displacement", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Mage\n25\nUse: Permanently teaches you this glyph.\n\nBlink now has 2 charges, gaining a charge every 15 sec, but no longer frees the caster from stuns and bonds." }
entries[56984] = { ["name"] = "Glyph of Mana Gem", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ethereal Ink (3)\nMajor Glyph\nClasses: Mage\n25\nUse: Permanently teaches you this glyph.\n\nYour Conjure Mana Gem spell now creates a Brilliant Mana Gem, which holds up to 10 charges." }
entries[56986] = { ["name"] = "Glyph of Crittermorph", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMinor Glyph\nClasses: Mage\n25\nUse: Permanently teaches you this glyph.\n\nWhen cast on critters, your Polymorph spells now last 24 hrs and can be cast on multiple targets." }
entries[56987] = { ["name"] = "Glyph of Polymorph", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Mage\n25\nUse: Permanently teaches you this glyph.\n\nYour Polymorph spell also removes all damage over time effects from the target." }
entries[56988] = { ["name"] = "Glyph of Icy Veins", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Mage\n25\nUse: Permanently teaches you this glyph.\n\nYour Icy Veins causes your Frostbolt, Frostfire Bolt, Ice Lance, and your Water Elemental's Waterbolt spells to split into 3 smaller bolts that each do 40% damage, instead of increasing spell casting speed." }
entries[56989] = { ["name"] = "Glyph of Spellsteal", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Mage\n25\nUse: Permanently teaches you this glyph.\n\nSpellsteal now also heals you for 5% of your maximum health when it successfully steals a spell." }
entries[56990] = { ["name"] = "Glyph of Remove Curse", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Mage\n25\nUse: Permanently teaches you this glyph.\n\nIncreases the damage you deal by 5% for 10 sec after you successfully remove a curse." }
entries[56991] = { ["name"] = "Glyph of Arcane Power", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ethereal Ink (3)\nMajor Glyph\nClasses: Mage\n25\nUse: Permanently teaches you this glyph.\n\nIncreases the duration and cooldown of Arcane Power by 100%." }
entries[56994] = { ["name"] = "Glyph of Aspects", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Jadefire Ink (3)\nMinor Glyph\nClasses: Hunter\n25\nUse: Permanently teaches you this glyph.\n\nEach time you activate a new Aspect, an animal companion representing that Aspect will follow you for 15 sec." }
entries[56995] = { ["name"] = "Glyph of Camouflage", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Lion's Ink (3)\nMajor Glyph\nClasses: Hunter\n25\nUse: Permanently teaches you this glyph.\n\nYour Camouflage ability now provides stealth even while moving, but your movement speed while Camouflage is active is reduced by 50%." }
entries[56996] = { ["name"] = "Glyph of Liberation", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Hunter\n25\nUse: Permanently teaches you this glyph.\n\nWhen you Disengage, you are healed for 5% of your total health." }
entries[56997] = { ["name"] = "Glyph of Mending", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Lion's Ink (3)\nMajor Glyph\nClasses: Hunter\n25\nUse: Permanently teaches you this glyph.\n\nYour Mend Pet now heals every 1 sec, and heals for an additional 25% of your pet's health over its duration." }
entries[56998] = { ["name"] = "Glyph of Distracting Shot", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Hunter\n25\nUse: Permanently teaches you this glyph.\n\nYour Distracting Shot now distracts the target to attack your pet instead of you." }
entries[56999] = { ["name"] = "Glyph of Endless Wrath", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Hunter\n25\nUse: Permanently teaches you this glyph.\n\nWhile Bestial Wrath is active, your pet cannot be killed, but can still be damaged." }
entries[57000] = { ["name"] = "Glyph of Deterrence", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Celestial Ink (3)\nMajor Glyph\nClasses: Hunter\n25\nUse: Permanently teaches you this glyph.\n\nIncreases the damage reduction granted by Deterrence by 20%." }
entries[57001] = { ["name"] = "Glyph of Disengage", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Celestial Ink (3)\nMajor Glyph\nClasses: Hunter\n25\nUse: Permanently teaches you this glyph.\n\nIncreases the distance you travel when you Disengage." }
entries[57002] = { ["name"] = "Glyph of Freezing Trap", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Shimmering Ink (3)\nMajor Glyph\nClasses: Hunter\n25\nUse: Permanently teaches you this glyph.\n\nWhen your Freezing Trap breaks, the victim's movement speed is reduced by 70% for 4 sec." }
entries[57003] = { ["name"] = "Glyph of Ice Trap", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ethereal Ink (3)\nMajor Glyph\nClasses: Hunter\n25\nUse: Permanently teaches you this glyph.\n\nIncreases the radius of the effect from your Ice Trap by 2 yards." }
entries[57004] = { ["name"] = "Glyph of Misdirection", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Midnight Ink (3)\nMajor Glyph\nClasses: Hunter\n25\nUse: Permanently teaches you this glyph.\n\nWhen you use Misdirection on your pet, the cooldown on your Misdirection is reset." }
entries[57005] = { ["name"] = "Glyph of Explosive Trap", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Lion's Ink (3)\nMajor Glyph\nClasses: Hunter\n25\nUse: Permanently teaches you this glyph.\n\nYour Explosive Trap no longer deals damage, instead knocking enemies back from the trap when it explodes." }
entries[57006] = { ["name"] = "Glyph of Animal Bond", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Hunter\n25\nUse: Permanently teaches you this glyph.\n\nWhile your pet is active, all healing done to you and your pet is increased by 10%." }
entries[57007] = { ["name"] = "Glyph of No Escape", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Jadefire Ink (3)\nMajor Glyph\nClasses: Hunter\n25\nUse: Permanently teaches you this glyph.\n\nIncreases the ranged critical strike chance of all of your attacks on targets affected by your Freezing Trap by 100%." }
entries[57008] = { ["name"] = "Glyph of Pathfinding", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ethereal Ink (3)\nMajor Glyph\nClasses: Hunter\n25\nUse: Permanently teaches you this glyph.\n\nIncreases the speed bonus of your Aspect of the Cheetah and Aspect of the Pack by 8%, and increases your speed while mounted by 10%. The mounted movement speed increase does not stack with other effects." }
entries[57009] = { ["name"] = "Glyph of Tame Beast", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Midnight Ink (3)\nMinor Glyph\nClasses: Hunter\n25\nUse: Permanently teaches you this glyph.\n\nReduces the time required to complete Tame Beast by 4 sec." }
entries[57010] = { ["name"] = "Glyph of Snake Trap", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Hunter\n25\nUse: Permanently teaches you this glyph.\n\nSnakes from your Snake Trap take 90% reduced damage from area of effect attacks." }
entries[57011] = { ["name"] = "Glyph of Aimed Shot", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Hunter\n25\nUse: Permanently teaches you this glyph.\n\nYour Aimed Shot can now be used while moving." }
entries[57012] = { ["name"] = "Glyph of Mend Pet", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Hunter\n25\nUse: Permanently teaches you this glyph.\n\nGives your Mend Pet ability a 100% chance of cleansing 1 Curse, Disease, Magic or Poison effect from your pet each tick." }
entries[57014] = { ["name"] = "Glyph of Solace", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Hunter\n25\nUse: Permanently teaches you this glyph.\n\nYour Freezing Trap and Scatter Shot also remove all damage over time effects from their targets." }
entries[57019] = { ["name"] = "Glyph of Focused Shield", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Paladin\n25\nUse: Permanently teaches you this glyph.\n\nYour Avenger's Shield hits 2 fewer targets, but for 30% more damage." }
entries[57020] = { ["name"] = "Glyph of Final Wrath", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Jadefire Ink (3)\nMajor Glyph\nClasses: Paladin\n25\nUse: Permanently teaches you this glyph.\n\nYour Holy Wrath does an additional 50% damage to targets with less than 20% health." }
entries[57021] = { ["name"] = "Glyph of the Harsh Word", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nGlyph of Harsh Words\nMajor Glyph\nClasses: Paladin\n25\nUse: Permanently teaches you this glyph.\n\nYour Word of Glory can now also be used on enemy targets, causing Holy damage approximately equal to the amount it would have healed.\n\nDoes not work with Eternal Flame." }
entries[57022] = { ["name"] = "Glyph of Divine Protection", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Midnight Ink (3)\nMajor Glyph\nClasses: Paladin\n25\nUse: Permanently teaches you this glyph.\n\nReduces the magical damage reduction of your Divine Protection to 20% but adds 20% physical damage reduction." }
entries[57023] = { ["name"] = "Glyph of Consecration", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Celestial Ink (3)\nMajor Glyph\nClasses: Paladin\n25\nUse: Permanently teaches you this glyph.\n\nYou can now target Consecration anywhere within 25 yards." }
entries[57024] = { ["name"] = "Glyph of Avenging Wrath", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Celestial Ink (3)\nMajor Glyph\nClasses: Paladin\n25\nUse: Permanently teaches you this glyph.\n\nWhile Avenging Wrath is active, you are healed for 1% of your maximum health every 2 sec." }
entries[57025] = { ["name"] = "Glyph of Blinding Light", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Shimmering Ink (3)\nMajor Glyph\nClasses: Paladin\n25\nUse: Permanently teaches you this glyph.\n\nYour Blinding Light now knocks down targets for 3 sec instead of Blinding them." }
entries[57026] = { ["name"] = "Glyph of Word of Glory", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ethereal Ink (3)\nMajor Glyph\nClasses: Paladin\n25\nUse: Permanently teaches you this glyph.\n\nIncreases your damage by 3% per Holy Power spent after you cast Word of Glory or Eternal Flame on a friendly target. Lasts 6 sec." }
entries[57027] = { ["name"] = "Glyph of Holy Wrath", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Midnight Ink (3)\nMajor Glyph\nClasses: Paladin\n25\nUse: Permanently teaches you this glyph.\n\nYour Holy Wrath now also stuns Elementals, Dragonkin, and Aberrations." }
entries[57028] = { ["name"] = "Glyph of Templar's Verdict", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Paladin\n25\nUse: Permanently teaches you this glyph.\n\nYou take 10% less damage for 6 sec after dealing damage with Templar's Verdict or Exorcism." }
entries[57029] = { ["name"] = "Glyph of Illumination", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Lion's Ink (3)\nClasses: Paladin\n25\nUse:\nYour Holy Shock criticals grant 1% mana return, but Meditation returns 10% less mana." }
entries[57030] = { ["name"] = "Glyph of Double Jeopardy", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Lion's Ink (3)\nMajor Glyph\nClasses: Paladin\n25\nUse: Permanently teaches you this glyph.\n\nJudging a target increases the damage of your next Judgment by 20%, but only if used on a different second target." }
entries[57031] = { ["name"] = "Glyph of Divinity", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Lion's Ink (3)\nMajor Glyph\nClasses: Paladin\n25\nUse: Permanently teaches you this glyph.\n\nIncreases the cooldown of your Lay on Hands by 2 min but causes it to give you 10% of your maximum mana." }
entries[57032] = { ["name"] = "Glyph of the Luminous Charger", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Jadefire Ink (3)\nMinor Glyph\nClasses: Paladin\n25\nUse: Permanently teaches you this glyph.\n\nYour Paladin class mounts glow with holy light." }
entries[57033] = { ["name"] = "Glyph of Devotion Aura", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ethereal Ink (3)\nMajor Glyph\nClasses: Paladin\n25\nUse: Permanently teaches you this glyph.\n\nDevotion Aura no longer affects party or raid members, but the cooldown is reduced by 60 sec." }
entries[57034] = { ["name"] = "Glyph of Blessed Life", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Paladin\n25\nUse: Permanently teaches you this glyph.\n\nYou have a 50% chance to gain a charge of Holy Power whenever you are affected by a Stun, Fear or Immobilize effect.\n\nThis effect cannot occur more than once every 20 sec. (Proc chance: 50%, 20s cooldown)" }
entries[57035] = { ["name"] = "Glyph of Light of Dawn", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Paladin\n25\nUse: Permanently teaches you this glyph.\n\nLight of Dawn affects 2 fewer targets, but heals each target for 25% more." }
