entries[57183] = { ["name"] = "Glyph of Purify", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Celestial Ink (3)\nMajor Glyph\nClasses: Priest\n25\nUse: Permanently teaches you this glyph.\n\nYour Purify spell also heals your target for 5% of maximum health when you successfully dispel a magical effect or disease." }
entries[57184] = { ["name"] = "Glyph of Fade", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Lion's Ink (3)\nMajor Glyph\nClasses: Priest\n25\nUse: Permanently teaches you this glyph.\n\nYour Fade ability now also reduces all damage taken by 10%." }
entries[57185] = { ["name"] = "Glyph of Fear Ward", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Shimmering Ink (3)\nMajor Glyph\nClasses: Priest\n25\nUse: Permanently teaches you this glyph.\n\nReduces the cooldown of Fear Ward by 60 sec." }
entries[57186] = { ["name"] = "Glyph of Inner Sanctum", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Lion's Ink (3)\nMajor Glyph\nClasses: Priest\n25\nUse: Permanently teaches you this glyph.\n\nSpell damage taken is reduced by 6% while within Inner Fire, and the movement speed bonus of your Inner Will is increased by 6%." }
entries[57187] = { ["name"] = "Glyph of Holy Nova", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ethereal Ink (3)\nMajor Glyph\nClasses: Priest\n25\nUse: Permanently teaches you this glyph.\n\nTeaches you the ability Holy Nova.\n\nCauses an explosion of holy light around the caster, causing 13 Holy damage to all enemy targets within 10 yards and healing up to 5 targets within 10 yards for 20 .\n\nHealing is divided among the number of targets healed. These effects cause no threat." }
entries[57188] = { ["name"] = "Glyph of Inner Fire", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Lion's Ink (3)\nMajor Glyph\nClasses: Priest\n25\nUse: Permanently teaches you this glyph.\n\nIncreases the armor gained from your Inner Fire spell by 50%." }
entries[57189] = { ["name"] = "Glyph of Lightwell", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nGlyph of Deep Wells\nMajor Glyph\nClasses: Priest\n25\nUse: Permanently teaches you this glyph.\n\nIncreases the total amount of charges of your Lightwell by 2." }
entries[57190] = { ["name"] = "Glyph of Mass Dispel", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Priest\n25\nUse: Permanently teaches you this glyph.\n\nCauses your Mass Dispel to be potent enough to remove Magic effects that are normally undispellable." }
entries[57191] = { ["name"] = "Glyph of Psychic Horror", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Priest\n25\nUse: Permanently teaches you this glyph.\n\nReduces the cooldown of your Psychic Horror by 10 sec." }
entries[57192] = { ["name"] = "Glyph of Holy Fire", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ethereal Ink (3)\nMajor Glyph\nClasses: Priest\n25\nUse: Permanently teaches you this glyph.\n\nIncreases the range of your Holy Fire, Smite, and Power Word: Solace spells by 10 yards." }
entries[57193] = { ["name"] = "Glyph of Weakened Soul", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Priest\n25\nUse: Permanently teaches you this glyph.\n\nReduces the duration of the Weakened Soul effect caused by Power Word: Shield by 2 sec." }
entries[57194] = { ["name"] = "Glyph of Power Word: Shield", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Midnight Ink (3)\nMajor Glyph\nClasses: Priest\n25\nUse: Permanently teaches you this glyph.\n\n20% of the absorb from your Power Word: Shield spell is converted into healing." }
entries[57195] = { ["name"] = "Glyph of Spirit of Redemption", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Priest\n25\nUse: Permanently teaches you this glyph.\n\nIncreases the duration of Spirit of Redemption by 10 sec." }
entries[57196] = { ["name"] = "Glyph of Psychic Scream", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Midnight Ink (3)\nMajor Glyph\nClasses: Priest\n25\nUse: Permanently teaches you this glyph.\n\nTargets of your Psychic Scream and your Psyfiend's Psychic Terror now tremble in place instead of fleeing in fear." }
entries[57197] = { ["name"] = "Glyph of Renew", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Jadefire Ink (3)\nMajor Glyph\nClasses: Priest\n25\nUse: Permanently teaches you this glyph.\n\nYour Renew heals for 33% more each time it heals, but its duration is reduced by 3 sec." }
entries[57198] = { ["name"] = "Glyph of Scourge Imprisonment", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Priest\n25\nUse: Permanently teaches you this glyph.\n\nReduces the cast time of your Shackle Undead by 1.0 sec." }
entries[57199] = { ["name"] = "Glyph of Mind Blast", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Priest\n25\nUse: Permanently teaches you this glyph.\n\nWhen you critically hit with your Mind Blast, you cause the target to be unable to move for 4 sec." }
entries[57200] = { ["name"] = "Glyph of Dispel Magic", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Jadefire Ink (3)\nMajor Glyph\nClasses: Priest\n25\nUse: Permanently teaches you this glyph.\n\nYour Dispel Magic spell also damages your target for 30 Holy damage when you successfully dispel a magical effect." }
entries[57201] = { ["name"] = "Glyph of Smite", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Celestial Ink (3)\nMajor Glyph\nClasses: Priest\n25\nUse: Permanently teaches you this glyph.\n\nYour Smite spell inflicts an additional 20% damage against targets afflicted by [ Solace and Insanity : Power Word: Solace / Holy Fire], but that additional damage does not get transferred by Atonement." }
entries[57202] = { ["name"] = "Glyph of Prayer of Mending", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Priest\n25\nUse: Permanently teaches you this glyph.\n\nThe first charge of your Prayer of Mending heals for an additional 60% but your Prayer of Mending has 1 fewer charge." }
entries[57207] = { ["name"] = "Glyph of Anti-Magic Shell", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Death Knight\n25\nUse: Permanently teaches you this glyph.\n\nCauses your Anti-Magic Shell to absorb all incoming magical damage, up to the absorption limit." }
entries[57208] = { ["name"] = "Glyph of Unholy Frenzy", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Death Knight\n25\nUse: Permanently teaches you this glyph.\n\nCauses your Unholy Frenzy to no longer deal damage to the affected target." }
entries[57209] = { ["name"] = "Glyph of the Geist", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ethereal Ink (3)\nMinor Glyph\nClasses: Death Knight\n25\nUse: Permanently teaches you this glyph.\n\nYour Raise Dead spell summons a geist instead of a ghoul." }
entries[57210] = { ["name"] = "Glyph of Icebound Fortitude", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Shimmering Ink (3)\nMajor Glyph\nClasses: Death Knight\n25\nUse: Permanently teaches you this glyph.\n\nReduces the cooldown of your Icebound Fortitude by 50%, but also reduces its duration by 75%." }
entries[57211] = { ["name"] = "Glyph of Chains of Ice", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Death Knight\n25\nUse: Permanently teaches you this glyph.\n\nYour Chains of Ice also causes 144 to 156 Frost damage, with additional damage depending on your attack power." }
entries[57213] = { ["name"] = "Glyph of Death Grip", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Shimmering Ink (3)\nMajor Glyph\nClasses: Death Knight\n25\nUse: Permanently teaches you this glyph.\n\nIncreases the range of your Death Grip ability by 5 yards." }
entries[57214] = { ["name"] = "Glyph of Death and Decay", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Death Knight\n25\nUse: Permanently teaches you this glyph.\n\nYour Death and Decay also reduces the movement speed of enemies within its radius by 50%." }
entries[57215] = { ["name"] = "Glyph of Death's Embrace", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ethereal Ink (3)\nMinor Glyph\nClasses: Death Knight\n25\nUse: Permanently teaches you this glyph.\n\nYour Death Coil refunds 20 Runic Power when used to heal an allied minion, but will no longer trigger Blood Tap when used this way." }
entries[57216] = { ["name"] = "Glyph of Shifting Presences", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Shimmering Ink (3)\nMajor Glyph\nClasses: Death Knight\n25\nUse: Permanently teaches you this glyph.\n\nYou retain 70% of your Runic Power when switching Presences. (Proc chance: 10%)" }
entries[57217] = { ["name"] = "Glyph of Horn of Winter", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ethereal Ink (3)\nMinor Glyph\nClasses: Death Knight\n25\nUse: Permanently teaches you this glyph.\n\nWhen used outside of combat, your Horn of Winter ability causes a brief, localized snow flurry." }
entries[57219] = { ["name"] = "Glyph of Icy Touch", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Shimmering Ink (3)\nMajor Glyph\nClasses: Death Knight\n25\nUse: Permanently teaches you this glyph.\n\nYour Icy Touch dispels one helpful Magic effect from the target." }
entries[57220] = { ["name"] = "Glyph of Enduring Infection", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Death Knight\n25\nUse: Permanently teaches you this glyph.\n\nYour diseases are undispellable, but their damage dealt is reduced by 15%." }
entries[57221] = { ["name"] = "Glyph of Pestilence", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ethereal Ink (3)\nMajor Glyph\nClasses: Death Knight\n25\nUse: Permanently teaches you this glyph.\n\nIncreases the radius of your Pestilence effect by 5 yards." }
entries[57222] = { ["name"] = "Glyph of Mind Freeze", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ethereal Ink (3)\nMajor Glyph\nClasses: Death Knight\n25\nUse: Permanently teaches you this glyph.\n\nReduces the cooldown of your Mind Freeze ability by 1 sec, but also raises its cost by 10 Runic Power." }
entries[57223] = { ["name"] = "Glyph of Army of the Dead", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMinor Glyph\nClasses: Death Knight\n25\nUse: Permanently teaches you this glyph.\n\nThe ghouls summoned by your Army of the Dead no longer taunt their target." }
entries[57224] = { ["name"] = "Glyph of Foul Menagerie", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ethereal Ink (3)\nMinor Glyph\nClasses: Death Knight\n25\nUse: Permanently teaches you this glyph.\n\nCauses your Army of the Dead spell to summon an assortment of undead minions." }
entries[57225] = { ["name"] = "Glyph of Strangulate", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Death Knight\n25\nUse: Permanently teaches you this glyph.\n\nIncreases the Silence duration of your Strangulate ability by 2 sec when used on a target who is casting a spell." }
entries[57226] = { ["name"] = "Glyph of Pillar of Frost", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ethereal Ink (3)\nMajor Glyph\nClasses: Death Knight\n25\nUse: Permanently teaches you this glyph.\n\nEmpowers your Pillar of Frost, making you immune to all effects that cause loss of control of your character, but also reduces your movement speed by 70% while the ability is active." }
entries[57227] = { ["name"] = "Glyph of Vampiric Blood", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ethereal Ink (3)\nMajor Glyph\nClasses: Death Knight\n25\nUse: Permanently teaches you this glyph.\n\nIncreases the bonus healing received while your Vampiric Blood is active by an additional 15%, but your Vampiric Blood no longer grants you health." }
entries[57228] = { ["name"] = "Glyph of Death Gate", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ethereal Ink (3)\nMinor Glyph\nClasses: Death Knight\n25\nUse: Permanently teaches you this glyph.\n\nReduces the cast time of your Death Gate spell by 60%." }
entries[57229] = { ["name"] = "Glyph of Path of Frost", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ethereal Ink (3)\nMinor Glyph\nClasses: Death Knight\n25\nUse: Permanently teaches you this glyph.\n\nYour Path of Frost ability allows you to fall from a greater distance without suffering damage." }
entries[57230] = { ["name"] = "Glyph of Resilient Grip", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ethereal Ink (3)\nMinor Glyph\nClasses: Death Knight\n25\nUse: Permanently teaches you this glyph.\n\nWhen your Death Grip ability fails because its target is immune, its cooldown is reset." }
entries[57232] = { ["name"] = "Glyph of Unstable Earth", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Shaman\n25\nUse: Permanently teaches you this glyph.\n\nCauses your Earthquake spell to also reduce the movement speed of affected targets by 40% for 3 sec." }
entries[57233] = { ["name"] = "Glyph of Chain Lightning", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Shaman\n25\nUse: Permanently teaches you this glyph.\n\nYour Chain Lightning spell now strikes 2 additional targets, but deals 10% less damage." }
entries[57234] = { ["name"] = "Glyph of Spirit Walk", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Shaman\n25\nUse: Permanently teaches you this glyph.\n\nReduces the cooldown of your Spirit Walk ability by 25%." }
entries[57235] = { ["name"] = "Glyph of Capacitor Totem", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Shaman\n25\nUse: Permanently teaches you this glyph.\n\nReduces the charging time of your Capacitor Totem by 2 sec." }
entries[57236] = { ["name"] = "Glyph of Purge", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ethereal Ink (3)\nMajor Glyph\nClasses: Shaman\n25\nUse: Permanently teaches you this glyph.\n\nYour Purge dispels 1 additional Magic effect but has a 6 sec cooldown." }
entries[57237] = { ["name"] = "Glyph of Fire Elemental Totem", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Shaman\n25\nUse: Permanently teaches you this glyph.\n\nReduces the cooldown and duration of your Fire Elemental Totem by 50%." }
entries[57238] = { ["name"] = "Glyph of Fire Nova", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Lion's Ink (3)\nMajor Glyph\nClasses: Shaman\n25\nUse: Permanently teaches you this glyph.\n\nIncreases the radius of your Fire Nova spell by 5 yards." }
entries[57239] = { ["name"] = "Glyph of Flame Shock", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Midnight Ink (3)\nMajor Glyph\nClasses: Shaman\n25\nUse: Permanently teaches you this glyph.\n\nWhen your Flame Shock deals damage, it heals you for 30% of the damage dealt." }
entries[57240] = { ["name"] = "Glyph of Wind Shear", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Lion's Ink (3)\nMajor Glyph\nClasses: Shaman\n25\nUse: Permanently teaches you this glyph.\n\nIncreases the school lockout duration of Wind Shear by 1 sec, but also increases the cooldown by 3 sec." }
entries[57241] = { ["name"] = "Glyph of Frost Shock", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Jadefire Ink (3)\nMajor Glyph\nClasses: Shaman\n25\nUse: Permanently teaches you this glyph.\n\nDecreases the cooldown incurred by your Frost Shock by 2 sec." }
entries[57242] = { ["name"] = "Glyph of Healing Stream Totem", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Celestial Ink (3)\nMajor Glyph\nClasses: Shaman\n25\nUse: Permanently teaches you this glyph.\n\nWhen your Healing Stream Totem heals an ally, it also reduces their Fire, Frost, and Nature damage taken by 10% for 6 sec." }
entries[57243] = { ["name"] = "Glyph of Healing Wave", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Shaman\n25\nUse: Permanently teaches you this glyph.\n\nYour Healing Wave also heals you for 20% of the healing effect when you heal someone else." }
entries[57244] = { ["name"] = "Glyph of Totemic Recall", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Celestial Ink (3)\nMajor Glyph\nClasses: Shaman\n25\nUse: Permanently teaches you this glyph.\n\nCauses your Totemic Recall ability to return the full mana cost of any recalled totems." }
entries[57245] = { ["name"] = "Glyph of Telluric Currents", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Lion's Ink (3)\nMajor Glyph\nClasses: Shaman\n25\nUse: Permanently teaches you this glyph.\n\nCauses your Lightning Bolt to restore 10 % of your mana when it strikes an enemy." }
entries[57246] = { ["name"] = "Glyph of the Lakestrider", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Midnight Ink (3)\nMinor Glyph\nClasses: Shaman\n25\nUse: Permanently teaches you this glyph.\n\nYou automatically gain Water Walking while you are in Ghost Wolf form." }
entries[57247] = { ["name"] = "Glyph of Grounding Totem", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Shaman\n25\nUse: Permanently teaches you this glyph.\n\nInstead of absorbing a spell, your Grounding Totem reflects the next harmful spell back at its caster, but the cooldown of your Grounding Totem is increased by 20 sec." }
entries[57248] = { ["name"] = "Glyph of Spiritwalker's Grace", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Shaman\n25\nUse: Permanently teaches you this glyph.\n\nIncreases the duration of your Spiritwalker's Grace by 5 sec." }
entries[57249] = { ["name"] = "Glyph of Lava Lash", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Jadefire Ink (3)\nMinor Glyph\nClasses: Shaman\n25\nUse: Permanently teaches you this glyph.\n\nYour Lava Lash ability no longer spreads Flame Shock to nearby targets." }
entries[57250] = { ["name"] = "Glyph of Chaining", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Shaman\n25\nUse: Permanently teaches you this glyph.\n\nIncreases the jump distance of your Chain Heal spell by 100%, but gives the spell a 2 sec cooldown." }
entries[57251] = { ["name"] = "Glyph of Water Shield", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Shimmering Ink (3)\nMajor Glyph\nClasses: Shaman\n25\nUse: Permanently teaches you this glyph.\n\nIncreases the mana generated reactively by your Water Shield when you are attacked by 50%, but reduces the passive mana generation by 15%." }
entries[57252] = { ["name"] = "Glyph of Cleansing Waters", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ethereal Ink (3)\nMajor Glyph\nClasses: Shaman\n25\nUse: Permanently teaches you this glyph.\n\nWhen you dispel a harmful Magic or Curse effect from an ally, you also heal the target for 5% of your maximum health." }
entries[57253] = { ["name"] = "Glyph of Thunderstorm", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMinor Glyph\nClasses: Shaman\n25\nUse: Permanently teaches you this glyph.\n\nRemoves the knockback effect from your Thunderstorm spell." }
entries[57257] = { ["name"] = "Glyph of Hand of Gul'dan", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ethereal Ink (3)\nMinor Glyph\nClasses: Warlock\n25\nUse: Permanently teaches you this glyph.\n\nYour Hand of Gul'dan can now be targeted at a location." }
entries[57258] = { ["name"] = "Glyph of Conflagrate", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Warlock\n25\nUse: Permanently teaches you this glyph.\n\nConflagrate no longer requires Immolate to snare the target." }
entries[57259] = { ["name"] = "Glyph of Siphon Life", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Midnight Ink (3)\nMajor Glyph\nClasses: Warlock\n25\nUse: Permanently teaches you this glyph.\n\nYour [ Immolate ] Corruption spell will heal you for 0.5% of your maximum health when dealing [ Immolate : periodic ]damage." }
entries[57260] = { ["name"] = "Glyph of Verdant Spheres", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMinor Glyph\nClasses: Warlock\n25\nUse: Permanently teaches you this glyph.\n\n[ Destruction : When you have a Burning Ember, it appears around your character as a Verdant Sphere /\n\nAffliction, Demonology\nYour Soul Shards are transformed into Verdant Spheres ]" }
entries[57261] = { ["name"] = "Glyph of Nightmares", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMinor Glyph\nClasses: Warlock\n25\nUse: Permanently teaches you this glyph.\n\nYour Felsteed and Dreadsteed can cross water while running and leave a trail of flames." }
entries[57262] = { ["name"] = "Glyph of Fear", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Lion's Ink (3)\nMajor Glyph\nClasses: Warlock\n25\nUse: Permanently teaches you this glyph.\n\nYour Fear causes the target to tremble in place instead of fleeing in fear." }
entries[57263] = { ["name"] = "Glyph of Felguard", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMinor Glyph\nClasses: Warlock\n25\nUse: Permanently teaches you this glyph.\n\nYour Felguard will equip a random two-handed axe, sword or polearm from your backpack." }
entries[57264] = { ["name"] = "Glyph of Demon Training", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Warlock\n25\nUse: Permanently teaches you this glyph.\n\nImproves your demon's special abilities:\n\nYour [ Grimoire of Supremacy : Fel Imp / Imp]'s Firebolt cast time is reduced by 50% and fires in bursts of three.\n\nIncreases your [ Grimoire of Supremacy : Voidlord / Voidwalker]'s total armor by 10%.\n\nYour [ Grimoire of Supremacy : Shivarra and Archincubus / Succubus and Incubus]'s [ Grimoire of Supremacy : Mesmerizes / Seduction] ability also removes all damage over time effects from the target.\n\nWhen your [ Grimoire of Supremacy : Observer / Felhunter] uses [ Grimoire of Supremacy : Clone Magic / Devour Magic], you will also be healed for that amount.\n\nIncreases your [ Grimoire of Supremacy : Wrathguard / Felguard]'s total health by 20%." }
entries[57265] = { ["name"] = "Glyph of Health Funnel", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Lion's Ink (3)\nMinor Glyph\nClasses: Warlock\n25\nUse: Permanently teaches you this glyph.\n\nYour Health Funnel instantly restores 15% of your demon's health, but has a 10 sec. cooldown." }
entries[57266] = { ["name"] = "Glyph of Healthstone", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Midnight Ink (3)\nMajor Glyph\nClasses: Warlock\n25\nUse: Permanently teaches you this glyph.\n\nYou receive 100% more healing from using a healthstone, but the health is restored over 10 sec." }
entries[57267] = { ["name"] = "Glyph of Subtlety", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMinor Glyph\nClasses: Warlock\n25\nUse: Permanently teaches you this glyph.\n\nYour Soul Shards no longer display while out of combat." }
entries[57268] = { ["name"] = "Glyph of Curse of the Elements", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Warlock\n25\nUse: Permanently teaches you this glyph.\n\nCurse of the Elements hits 2 additional nearby targets." }
entries[57269] = { ["name"] = "Glyph of Imp Swarm", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Lion's Ink (3)\nMajor Glyph\nClasses: Warlock\n25\nUse: Permanently teaches you this glyph.\n\nTeaches you the ability Imp Swarm.\nRequires Demonology.\n\nImp Swarm\nSummons 4 Wild Imps from the Twisting Nether to attack the target.\n\nThe Wild Imps passive effect is disabled while Imp Swarm is on cooldown. Imp Swarm's cooldown is reduced by spell haste. Also increases Wild Imp's cooldown by 4 sec." }
entries[57270] = { ["name"] = "Glyph of Havoc", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Celestial Ink (3)\nMajor Glyph\nClasses: Warlock\n25\nUse: Permanently teaches you this glyph.\n\nHavoc gains 3 additional charges, but the cooldown is increased by 35 seconds." }
entries[57271] = { ["name"] = "Glyph of Shadow Bolt", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Jadefire Ink (3)\nMinor Glyph\nClasses: Warlock\n25\nUse: Permanently teaches you this glyph.\n\nSplits your Shadow Bolt into three smaller attacks." }
entries[57274] = { ["name"] = "Glyph of Soulstone", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Celestial Ink (3)\nMajor Glyph\nClasses: Warlock\n25\nUse: Permanently teaches you this glyph.\n\nPlayers resurrected by Soulstone are returned to life with 100% health." }
entries[57275] = { ["name"] = "Glyph of Carrion Swarm", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ethereal Ink (3)\nMinor Glyph\nClasses: Warlock\n25\nUse: Permanently teaches you this glyph.\n\nYour Carrion Swarm no longer knocks targets back." }
entries[57276] = { ["name"] = "Glyph of Unstable Affliction", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Warlock\n25\nUse: Permanently teaches you this glyph.\n\nReduces the cast time of Unstable Affliction by 25%." }
entries[57277] = { ["name"] = "Glyph of Falling Meteor", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Jadefire Ink (3)\nMinor Glyph\nClasses: Warlock\n25\nUse: Permanently teaches you this glyph.\n\nIf you use Demonic Leap while falling, you slam into the ground rapidly and will not die from falling damage." }
